using UnityEngine;
using Signspace.Matching;

namespace Signspace.Gaze
{
    /// <summary>
    /// Puts a gaze target on each fingertip of the reference hand (P6.1 step 2).
    ///
    /// WHY AT RUNTIME
    /// --------------
    /// The reference hand's joint transforms are generated by <see cref="HandVisual.Build"/>, which the
    /// scene builder calls when it writes the scene but which a saved scene does not replay. Creating
    /// the colliders in the editor would leave them on transforms that only exist in the builder's
    /// session. Building them here means the targets are on the same joints the pose is applied to, in
    /// every build, and the check can run the same code the build runs.
    ///
    /// The collider is a sphere, not a plane and not the bone capsule: a capsule along a finger is a
    /// 40 mm target lying flat, so the ray grazes it at exactly the angle a user looks from. A 11 mm
    /// sphere at the fingertip is generous without swallowing its neighbour (fingertips are ~15 mm
    /// apart at arm's length, ~25 mm at 0.6 m).
    ///
    /// GROUPS
    /// ------
    /// Every target also carries a coarse group (thumb / index / middle / ring+little). If P6.1's
    /// distance test shows single fingers are not resolvable, `useGroups` on the highlighter switches
    /// to them without rebuilding anything. The choice is deliberately a tick, not a rewrite.
    /// </summary>
    public class FingerTargetsBuilder : MonoBehaviour
    {
        public HandVisual visual;

        [Tooltip("Sphere radius at each fingertip, in metres at hand scale 1.")]
        public float radiusMetres = 0.011f;

        [Tooltip("Layer for the targets. Default is everything the gaze ray tests.")]
        public int layer = 0;

        /// <summary>How many targets exist. The check asserts this equals the number of long fingers + thumb.</summary>
        public int Count { get; private set; }

        public string Report { get; private set; } = "not built";

        void Awake()
        {
            if (visual == null) visual = FindReferenceVisual();
            Build();
        }

        /// <summary>Idempotent: calling it again replaces the targets instead of stacking them.</summary>
        public int Build()
        {
            Count = 0;
            if (visual == null)
            {
                Report = "no reference HandVisual";
                Debug.LogWarning("[FingerTargetsBuilder] no reference HandVisual; there is nothing to aim at.");
                return 0;
            }

            if (visual.joints == null || visual.joints.Length < 26)
            {
                // A cold scene can have the component without its generated rig.
                visual.Build();
            }

            var joints = visual.joints;
            if (joints == null || joints.Length < 26)
            {
                Report = "the hand rig has " + (joints == null ? 0 : joints.Length) + " joints, expected 26";
                Debug.LogWarning("[FingerTargetsBuilder] " + Report);
                return 0;
            }

            float scale = Mathf.Max(0.01f, visual.scale);
            var names = new[] { "thumb", "index", "middle", "ring", "little" };
            var groups = new[] { 0, 1, 2, 3, 3 };

            for (int f = 0; f < 5; f++)
            {
                // The distal joint is the last one carrying shape; the tip joint is one past it and is
                // where a user actually aims, so the target sits there.
                int tipIndex = Mathf.Min(joints.Length - 1, PoseMath.FingerChainEnd[f] + 1);
                var joint = joints[tipIndex];
                if (joint == null) continue;

                var existing = joint.GetComponent<FingerTarget>();
                var go = existing != null ? existing.gameObject : joint.gameObject;

                var sphere = go.GetComponent<SphereCollider>();
                if (sphere == null) sphere = go.AddComponent<SphereCollider>();
                sphere.isTrigger = true;
                sphere.radius = radiusMetres / scale;    // joint transforms inherit the hand's scale
                sphere.center = Vector3.zero;

                var target = go.GetComponent<FingerTarget>();
                if (target == null) target = go.AddComponent<FingerTarget>();
                target.fingerIndex = f;
                target.label = names[f];
                target.group = groups[f];

                go.layer = layer;
                Count++;
            }

            Report = Count + " finger targets (" + string.Join(", ", names) + "), radius " +
                     (radiusMetres * 1000f).ToString("0") + " mm, hand scale " + scale.ToString("0.00");
            Debug.Log("[FingerTargetsBuilder] " + Report);
            return Count;
        }

        HandVisual FindReferenceVisual()
        {
            var hand = FindFirstObjectByType<ReferenceHand>();
            if (hand != null && hand.visual != null) return hand.visual;
            var all = FindObjectsByType<HandVisual>(FindObjectsSortMode.None);
            return all != null && all.Length > 0 ? all[0] : null;
        }
    }
}
